traps.Trap04.txt:
// 临安城外遇见张琳心

	If ($Event == 200) @Event200;
	Return;

@Event200:
	StopMusic();
	PlayMusic("情缘音乐.mp3");
	NpcGoto("张琳心", 18, 44);
	SetNpcDir("张琳心", 4); 
	SetPlayerDir(7);
	Say("张琳心：你的伤还没好，怎么到处跑？", 21);
	PlayerGoto(18, 42);
	SetPlayerDir(0);
	Say("独孤剑：是谁到处跑？我正在到处找你。", 1);
	Say("张琳心：我、我回客栈找不到你，还以为你走了，所以……", 24);
	PlayerGoto(19, 41);
	SetPlayerDir(5);
	Say("独孤剑：多谢张姑娘对我的关心。", 1);
	NpcGoto("张琳心", 18, 43);
	SetNpcDir("张琳心", 5);
	Say("张琳心：你……救过我的命，我——", 24);
	Say("独孤剑：……你现在也救了我一命，我们互不相欠了。", 1);
	Say("张琳心：你……为什么要这么说？", 28);
	Say("独孤剑：我还能怎么说？我爹死在你爹的手上，你叫我……怎么面对你？",  9);
	Say("张琳心：……", 26);
	//Watch("独孤剑", "张琳心", 0);
	SetPlayerDir(1);
	Say("独孤剑：你哥哥他怎么样了？", 1);
	Say("张琳心：哥哥他……和那个红衣人走了。", 24);
	Say("张琳心：原以为他这次回来会与爹爹和好，想不到，哥哥还是不肯原谅爹。",24);
	Say("独孤剑：……", 1);
	Sleep(500);
	Say("独孤剑：对了，我找你还有一件十分重要的事。你……可曾见到我身上的一封……血书？", 1);
	Say("张琳心：我帮你包扎伤口时，看到了那封血书，当时我爹爹也来了，他说这信很重要，便连夜赶去武夷山了。", 24);
	Say("独孤剑：啊？！什么？", 6);
	Say("张琳心：你……你不相信我？", 24);
	Say("独孤剑：我不相信你的父亲！我现在得马上赶去武夷山。", 9);
	Say("张琳心：可你的伤……", 24);
	Say("独孤剑：我的伤没事。", 1);
	Say("张琳心：那……我也去！", 24);
	Say("独孤剑：你去干什么？", 8);
	Say("张琳心：我去找我爹爹。", 24);
	PlayMusic("长路.mp3");
	SetNpcKind("张琳心",3);
	SetNpcRelation("张琳心", 0);
	SetNpcScript("张琳心", "张琳心对话.txt");
	SetNpcDeathScript("张琳心", "主角死亡.txt");
	SetNpcDeathScript("独孤剑", "主角死亡.txt");
	SetMapTrap(1, "trap01.txt");
	SetMapTrap(2, "trap02.txt");
	SetMapTrap(4, "");
	Assign($Event, 210);
	Memo("独孤剑再出南门，见到张琳心，得知血书被张风拿走，两人决定前往武夷山找张风和血书。");
	Return;

traps.trap03.txt:
// 在临安城南遇见张如梦

	If ($Event == 190) @Event190;
	Return;
	
@Event190:
	StopMusic();
	Say("独孤剑：张大哥！", 8);
	SetNpcDir("张如梦", 5);
	PlayerGoto(15, 36);
	SetPlayerDir(1);
	Say("独孤剑：张大哥，你怎么会在这里？", 1);
	Say("张如梦：独孤兄，小弟在此恭候多时了。", 11);
	Say("独孤剑：张大哥有何赐教？", 1);
	Say("张如梦：独孤兄行侠仗义，心怀坦荡，实在是江湖中少有的大丈夫。", 11);
	Say("独孤剑：张大哥何出此言？", 1);
	Say("张如梦：你在碧霞岛上的所作所为，我妹妹都给我讲了。", 11);
	Say("独孤剑：我没有想到，你……会是张风的儿子！", 9);
	Say("张如梦：虽然我不耻我父亲的行径，但是他毕竟是我的父亲。所谓父债子还，天经地义，独孤兄，动手吧！", 11);
	Say("独孤剑：张大哥，你我意气相投，一见如故，我原本十分庆幸自己结识了你这样的朋友，可是没想到，我们第二次见面便要刀剑相向，我……真是心痛！", 9);
	Say("张如梦：这也许就是天意吧！独孤兄，你我都是身不由己之人！多说无益，出招吧！", 11);
	Say("独孤剑：张大哥，得罪了！", 1);
	PlayMusic("沙场.mp3");
	SetNpcRelation("张如梦", 1);
	SetNpcDeathScript("张如梦", "张如梦打败.txt");
	SetPlayerState(1);
    EnableFight();
	EnableNpcAI();
	Assign($Event, 195);
	SetMapTrap(1, "trap01.txt");
	SetMapTrap(2, "trap02.txt");
	SetMapTrap(3, "");
	SetNpcPos("宋兵1", 0, 0);
	SetNpcPos("宋兵2", 0, 0);
	SetNpcPos("妇人", 0, 0);
	SetNpcPos("茶摊老板", 0, 0);
	SetNpcPos("卖药人", 0, 0);
	Return;
